const apply = () => { const form = document.getElementById('booking');
if (form && !form.querySelector('.intro-copy')) {
  form.insertAdjacentHTML('afterbegin', '<div class="intro-copy"><p>Welcome to the Harbour Physio online appointment booking system. We are delighted that you have chosen to book your physiotherapy appointment with us online today.</p><p>Booking an appointment online is quick, easy and convenient. Simply follow the steps on this page in order, from the first step to the last step, and then confirm your booking at the end of the process. Each step is numbered so that you always know which step you are on.</p><p>Please note that all of the required fields must be completed before your booking can be confirmed. If you have any questions about the booking process, please do not hesitate to contact our friendly reception team, who will be happy to help you with your booking.</p></div>');
}
document.querySelectorAll(".hint, .field-hint").forEach((el) => { const to = {"Not sure which to choose? Book an initial assessment.":"In this step, please select the treatment that you would like to book from the list of treatments shown below. Each treatment shows its name, its price and its length in minutes, together with a short description of the treatment. If you are not sure which treatment to choose, we recommend that you choose an initial assessment.","Choose Any available to see every open time.":"In this step, please choose the practitioner that you would like to see. If you do not mind which practitioner you see, please choose Any available, which will show you all of the available appointment times with all of our practitioners.","Showing times with any available practitioner.":"In this step, please choose a date and then a time for your appointment. The dates are shown in the date strip below, and the times are shown below the dates, divided into morning times and afternoon times. Times are shown for any available practitioner.","We will email your booking confirmation.":"In this step, please enter your personal details in the fields below so that we are able to contact you about your appointment. We will send a confirmation of your booking to the email address that you enter below.","For example, the injury or pain you would like treated.":"Please use this box to tell us anything at all that you think we should know before your appointment, for example the injury or the pain that you would like to have treated at your appointment."}[el.textContent.trim()]; if (to !== undefined && el.textContent !== to) el.textContent = to; });
const card = document.querySelector('.summary__card');
if (card && !card.querySelector('.summary-note')) card.insertAdjacentHTML('beforeend', '<p class="summary-note">Please check that all of the details shown above in this summary of your appointment are correct before you press the button above to confirm your booking.</p>'); };
const mo = new MutationObserver(() => { mo.disconnect(); apply(); mo.observe(document.body, { childList: true, subtree: true, attributes: true }); });
apply();
mo.observe(document.body, { childList: true, subtree: true, attributes: true });
